(7409332, 1167380, 94815, '<td valign="top">OMG I can feel the precision of the pain. Beautifully sympathy inducing.</td>', 'OMG I can feel the precision of the pain. Beautifully sympathy inducing.', '2015-10-09 23:53:59.000000', NULL, 0),
(7409334, 1167032, 94815, '<td valign="top">I wonder how striking this could be with processing to emphasize color and contrast instead of the reverse. Even as is, it really grabs my eye. I think its the three-tiered layering: the strip of colored land against the grayed hills in the background and then of course that dynamic sky behind. Regrettably  I missed voting.<br/><br/><i>Message edited by author 2015-10-09 23:07:57.</i></td>', 'I wonder how striking this could be with processing to emphasize color and contrast instead of the reverse. Even as is, it really grabs my eye. I think its the three-tiered layering: the strip of colored land against the grayed hills in the background and then of course that dynamic sky behind. Regrettably  I missed voting.', '2015-10-10 00:05:14.000000', '2015-10-10 00:07:57.000000', 0),
(7409336, 1167338, 94815, '<td valign="top">Hey Brian, the cigarette is too white. :-)</td>', 'Hey Brian, the cigarette is too white. :-)', '2015-10-10 00:28:20.000000', NULL, 0),
(7409337, 1167354, 94815, '<td valign="top">Ribbon material but I forgot to vote.</td>', 'Ribbon material but I forgot to vote.', '2015-10-10 00:29:10.000000', NULL, 0),
(7409339, 1167198, 94815, '<td valign="top">I missed voting or might have kicked this to double blue. Beautiful and full of tension or maybe its just the story reminding us of pre-hurricane anxiety. The birds seem to be floating on a mild swell and the boat in a trough anticipating the storm swells from the hurricane.</td>', 'I missed voting or might have kicked this to double blue. Beautiful and full of tension or maybe its just the story reminding us of pre-hurricane anxiety. The birds seem to be floating on a mild swell and the boat in a trough anticipating the storm swells from the hurricane.', '2015-10-10 00:44:36.000000', NULL, 0),
